def skill(robot):
    places = robot.places()
    pack = [p for p in places if "pack" in p.lower()][0]
    g = robot.ground_robot_position()
    f = robot.drone_fly_to(g[0], g[1], 1.3)
    robot.drone_set_wind_correction(max(-3, min(3, -6 * (f[0] - g[0]))), max(-3, min(3, -6 * (f[1] - g[1]))))
    for p in places:
        robot.drone_scan(p, ["banana", "soup can"])
    for t in ["banana", "soup can"]:
        rec = robot.recall(t)
        ord = ([rec] if rec in places else []) + [p for p in places if p != rec]
        ok = False
        for p in ord:
            if not robot.go_to(p):
                continue
            if robot.pick(t):
                ok = True
                break
        if not ok:
            return False
        if not robot.go_to(pack):
            return False
        if not robot.place_on("tray"):
            return False
    robot.start_driving()
    g = robot.ground_robot_position()
    robot.drone_fly_to(g[0], g[1], 1.3)
    p1 = robot.drone_find_pad()
    g1 = robot.ground_robot_position()
    robot.drone_fly_to(g1[0], g1[1], 1.3)
    p2 = robot.drone_find_pad()
    if not p1 or not p2:
        return False
    vx = (p2[0] - p1[0]) / 3.0
    vy = (p2[1] - p1[1]) / 3.0
    robot.drone_fly_to(p2[0] + vx * 3, p2[1] + vy * 3, 1.3)
    p3 = robot.drone_find_pad()
    if not p3:
        return robot.drone_land_at(p2[0] + vx * 5, p2[1] + vy * 5)
    vx = (p3[0] - p2[0]) / 3.0
    vy = (p3[1] - p2[1]) / 3.0
    return robot.drone_land_at(p3[0] + vx * 2, p3[1] + vy * 2)

